// This endpoint is publicly accessible
return    res  . json  (  getAllUsers  (  )  )  ;
}  )  ;


// Auth middleware applied here — too late for the admin route above
app  . use  (  requireAuth  )  ;


app  . get  (  '/api/users/profile'  ,    (  req  ,    res  )    =>    {
return    res  . json  (  req  . user  )  ;
}  )  ;
```


